<template><section class="note-list"><header><h3>笔记列表</h3><span>{{ notes.length }} 项</span></header><input v-model="query" placeholder="搜索笔记" aria-label="搜索笔记"/><div class="note-items"><div v-for="note in filtered" :key="note.id" class="note-item"><button class="note-open" :draggable="draggable" @dragstart="$emit('dragNote',{event:$event,note})" @dragend="$emit('dragFinish')" @click="$emit('open',note)"><span>▤ {{ note.title }}</span><small>{{ note.updated_at?.slice(0,10) }}</small></button><button aria-label="重命名笔记" @click="rename(note)">✎</button><button aria-label="删除笔记" @click="remove(note)">×</button></div><p v-if="!filtered.length">暂无笔记，可从最终报告点击 Note 创建。</p></div><p v-if="error" class="error">{{ error }}</p></section></template>
<script setup lang="ts">
import {ref,computed} from 'vue';import {api} from '../services/api';import type {PersonalNote} from '../services/notes';const props=defineProps<{notes:PersonalNote[];draggable?:boolean}>();const emit=defineEmits<{open:[note:PersonalNote];changed:[];dragNote:[payload:{event:DragEvent;note:PersonalNote}];dragFinish:[]}>();const query=ref('');const error=ref('');const filtered=computed(()=>props.notes.filter(n=>n.title.toLowerCase().includes(query.value.toLowerCase())));
async function rename(note:PersonalNote){const title=window.prompt('笔记标题',note.title);if(!title?.trim()||title===note.title)return;try{const current=await api<PersonalNote>('/notes/'+note.id);await api('/notes/'+note.id,{method:'PUT',body:JSON.stringify({...current,title:title.trim()})});emit('changed');}catch{error.value='重命名失败';}}
async function remove(note:PersonalNote){if(!window.confirm(`确定删除笔记“${note.title}”？`))return;try{await api('/notes/'+note.id,{method:'DELETE'});emit('changed');}catch{error.value='删除失败';}}
</script>
<style scoped>.note-list{min-height:100px;flex:0 0 auto}.note-list header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.note-list h3{font-size:14px;margin:0}.note-list header span{font-size:12px;color:#8899b3}.note-list input{width:100%;box-sizing:border-box;border:1px solid #d6e1f2;border-radius:8px;padding:9px;font:inherit;font-size:12px}.note-items{max-height:180px;overflow:auto;margin-top:8px}.note-item{display:flex;gap:3px;border-radius:8px;padding:5px;align-items:center}.note-item:hover{background:#edf3ff}button{border:0;background:none;color:#5f78a0;cursor:pointer}.note-open{flex:1;min-width:0;text-align:left;display:flex;flex-direction:column;gap:5px;padding:4px}.note-open span{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.note-open small,.note-items p{font-size:11px;color:#8594ad}.error{font-size:12px;color:#b73d4a}</style>
